// Cap error notifications
// You can get all this errors by typing "CAP_debugerror" in console.
// Also you can get specified error by typing "CAP_debugerror 9" for example.
sg_err_title = Ascension Gates - Erreur
sg_err_html_t = Erreur d'Ascension Gates:
sg_err_n = Erreur
sg_err_01 = L'addon Stargate Group System a été trouvé dans ton dossier d'installation de Garry's Mod. Cet addon est intégré à Ascension Gates et doit être supprimé pour résoudre les erreurs.
sg_err_02 = Ascension Gates n'est pas installé correctement.<br>Assure-toi que toutes les parties d'Ascension Gates sont installées et qu'aucun ancien addon de code CAP / CAP Enhanced / EAP n'est installé en même temps.
sg_err_03 = Le fichier de version de l'addon est corrompu !<br>Réinstalle Ascension Gates pour restaurer 'lua/cap_ver.lua'.
sg_err_04 = Un ancien pack Stargate est installé en même temps qu'Ascension Gates :%s<br><br>Rien n'est cassé. Ascension Gates contient déjà tout CAP et CAP Enhanced, avec de nombreux bugs corrigés. Mais les deux packs utilisent les mêmes fichiers et noms : avec les deux, la version d'un objet qui fonctionne est due au hasard, ce qui crée des erreurs dans les deux.<br><br>Désabonne-toi de l'ancien pack (lien ci-dessus) et redémarre le jeu. D'ici là, Ascension Gates ne fait rien apparaître. Tes sauvegardes et dupes continuent de fonctionner : les objets ont gardé leurs noms.
sg_err_05 = Abonne-toi à tous les éléments du Workshop nécessaires pour que l'addon fonctionne correctement.<br><br>Addons manquants :%s
sg_err_06 = Ton Garry's Mod n'est pas à jour. Installe la dernière version !
sg_err_07 = Wiremod est introuvable.<br>Vérifie que Wiremod est correctement installé.
sg_err_08 = Tu utilises la bêta de Garry's Mod 13, qui ne prend plus en charge cet addon. Utilise la version officielle et à jour de Garry's Mod !
sg_err_09 = Ascension Gates n'est pas installé correctement.<br>Vérifie que toutes les parties d'Ascension Gates sont installées et qu'aucun ancien addon de code CAP / CAP Enhanced / EAP n'est installé en même temps.
sg_err_10 = Tu as en même temps la version workshop et la version github de cap_resources.<br>Supprime l'une des deux : efface le dossier cap_resources de ton dossier addons ou désabonne-toi depuis la collection du workshop.
sg_err_11 =[[Ascension Gates n'est pas installé correctement.<br>Assure-toi que toutes les parties d'Ascension Gates sont installées et qu'aucun ancien addon de code CAP / CAP Enhanced / EAP n'est installé en même temps.
]]
sg_err_12 = Les ressources d'Ascension Gates ne sont plus à jour !<br>Mets-les à jour.
sg_err_13 = [[Anciens fichiers du Workshop détectés.
<br>Supprime ces fichiers du dossier :
<br>"%s"
<br>%s
]]
sg_err_14 = [[Ton Wiremod n'est plus à jour. Mets-le à jour pour qu'Ascension Gates fonctionne entièrement.
<br>Cette version de Wiremod est ancienne et n'est plus mise à jour. Utilise plutôt la version du Steam Workshop ou de GitHub.
<br>
<br>Steam Workshop : <a href='https://steamcommunity.com/sharedfiles/filedetails/?id=160250458'>https://steamcommunity.com/sharedfiles/filedetails/?id=160250458</a>
<br>GitHub : <u>https://github.com/wiremod/wire</u>
]]